  ['谢昭宁', '好感度'],
];

const dailyAffectionLimit = 12;

function normalizeRelationshipScore(value) {
  const score = Number(value);
  return Number.isFinite(score) ? Math.max(0, Math.min(100, Math.round(score))) : undefined;
}

function limitRelationshipGains(state, before) {
  if (!state) return;

  const previous = before?.剧情?.当日好感增量;
  const trackedDay = campusDate(previous?.日期);
  const day = [trackedDay, campusDate(before?.世界?.日期), campusDate(state.世界?.日期)].sort().at(-1);
  // 日期更正或暂缺时沿用本剧情分支的额度，直到剧情推进到更晚的一天。
  const previousUsage = !trackedDay || trackedDay === day ? previous?.已用 : undefined;
  const usage = {};

  for (const [person, metric] of relationshipMetrics) {
    const character = state[person];
    const score = normalizeRelationshipScore(character?.[metric]);

    if (score !== undefined) character[metric] = score;
    if (metric !== '好感度' || !before) continue;

    const already = Math.min(dailyAffectionLimit, normalizeRelationshipScore(previousUsage?.[person]) ?? 0);
    if (already) usage[person] = already;
    if (score === undefined) continue;

    const oldScore = normalizeRelationshipScore(before[person]?.[metric]) ?? 0;
    if (score > oldScore) {
      const gain = Math.min(score - oldScore, dailyAffectionLimit - already);
      character[metric] = oldScore + gain;
      if (gain) usage[person] = already + gain;
    }
  }

  if (before) (state.剧情 ??= {}).当日好感增量 = { 日期: day, 已用: usage };

  if (state.剧情) {
    delete state.剧情.当日关系增量;
    delete state.剧情.重大情感申请;
    delete state.剧情.已结算重大情感事件;
    delete state.剧情.推进节奏;
    delete state.剧情.事件冷却;
    delete state.剧情.上次焦点角色;
  }
}
const periodDates = [{"id":"高二上","start":[0,"08-01"],"end":[1,"02-20"]},{"id":"高二下","start":[1,"02-21"],"end":[1,"06-30"]},{"id":"暑假","start":[1,"07-01"],"end":[1,"08-31"]},{"id":"高三上","start":[1,"09-01"],"end":[2,"02-20"]},{"id":"高三下","start":[2,"02-21"],"end":[2,"06-30"]},{"id":"已毕业","start":[2,"07-01"],"end":[99,"12-31"]}];
const activityIds = ["opening","national","sports","midterm","hike","new-year","winter","spring-festival","arts","study-trip","summer-practice","coming-of-age","graduation-night"];


$(async () => {
  registerMvuSchema(Schema);
  const niananSchema = Schema.unwrap().shape.许念安;
  await waitGlobalInitialized('Mvu');
  eventOn(Mvu.events.VARIABLE_UPDATE_STARTED, ({ stat_data }) => {
    if (stat_data) stat_data.许念安 ??= niananSchema.parse({});
  });
  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (variables, before) => {
    limitRelationshipGains(variables?.stat_data, before?.stat_data);
  });
  eventOn(Mvu.events.BEFORE_MESSAGE_UPDATE, ({ variables }) => {
    const state = variables?.stat_data;
    if (state) {
      const character = niananSchema.safeParse(state.许念安 ?? {});
      if (character.success) state.许念安 = character.data;
    }
    // MVU carries old fields forward. Retire these keys on the newly written floor only.
    delete state?.凌知夏;
    delete state?.云清晏?.已入班;
    delete state?.剧情?.当日关系增量;
    delete state?.剧情?.重大情感申请;
    delete state?.剧情?.已结算重大情感事件;
    delete state?.剧情?.推进节奏;
    delete state?.剧情?.事件冷却;
    delete state?.剧情?.上次焦点角色;
    const period = campusPeriod(periodDates, state?.世界?.日期, campusYear(state?.世界?.起始年份), state?.剧情?.学期);
    if (period && state.剧情) state.剧情.学期 = period.id;
    if (state?.剧情?.灵气复苏?.已开启) {
      const toMs = (raw) => {
        const m = String(raw || '').trim().match(/^(\d{4})[-/年.](\d{1,2})[-/月.](\d{1,2})/);
        return m ? Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
      };
      const ori = toMs(state.剧情.灵气复苏.开启日期) ?? toMs(state?.世界?.日期);
      const cur = toMs(state?.世界?.日期) ?? ori;
      if (ori !== null && cur !== null) {
        const d = Math.max(0, Math.floor((cur - ori) / 86400000));
        state.剧情.灵气复苏.阶段 = d < 10 ? '微兆潜龙期' : d < 25 ? '古武抬头期' : d < 45 ? '龙眼破禁期' : d < 90 ? '潜龙秘序期' : '百宗出山期';
      }
    }
    if (state?.主角) {
      const age = campusAgeAt(state.主角.出生日期, state.世界?.日期);
      if (age !== null) state.主角.年龄 = `${age}岁`;
      state.主角.班级 = campusPlayerClass(state.主角.班级, period?.id);
    }
    if (!state?.校园) return;
    state.校园 = normalizeCampus(state.校园, state.世界?.日期, activityIds);
    for (const post of [...state.校园.有效公告, ...state.校园.动态流]) {
      if (Array.isArray(post.点赞) || Array.isArray(post.互动)) {
        Object.assign(post, CampusInteractions.parse(post));
      }
    }
  });
});

