        stat.云清晏 ??= {
          是否在场: false,
          好感度: 0,
          关系阶段: '观澜',
          NSFW: false,
          当前境界: '金丹跌境（重创封蛰）',
          伤势余韵: '元婴劫伤未愈·阴雨畏寒',
          当前上装: '洗得规整的暨阳中学白衬衣校服与领结',
          当前下装: '深青校裙与过踝袜鞋',
          所在位置: progress.dayNumber === 1 ? '暨阳城外·赴约途中' : '待确定',
          动作: '',
          心情: '',
          内心独白: '',
        };
        stat.谢昭宁 ??= {
          是否在场: false,
          好感度: 0,
          关系阶段: '观风',
          NSFW: false,
